          mixBlendMode: "multiply",
          animationName: moving ? animation : "none",
          animationDuration: `${Math.max(400, duration)}ms`,
          animationIterationCount: "infinite",
          animationDirection: "alternate",
          animationPlayState: moving ? "running" : "paused",
        }}
