function NumberFlow({
  value,
  locales,
  format,
  prefix,
  suffix,
  className,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: NumberFlowProps) {
  const styled = textStyle(undefined, fontSize, fontWeight, letterSpacing, align)
  const flow = (
