      value={value}
      locales={locales}
      format={format}
      prefix={prefix}
      suffix={suffix}
      className={className}
    />
  )
  if (styled === undefined) return flow
  return (
    <span className={className} style={styled}>
      {flow}
    </span>
  )
}

