// Ported from beUI (MIT, (c) 2026 Saurabh Chauhan) — https://github.com/starc007/ui-components/blob/main/components/motion/overflow-actions.tsx


import { MoreHorizontal, X } from "lucide-react";
import {
  AnimatePresence,
  motion,
    type Transition,
  type Variants,
} from "motion/react";
import {
