// Ported from SyntaxUI (MIT, (c) 2024 SyntaxUI) — https://github.com/SyntaxUI/syntaxui/blob/main/src/showcase/components/loaders/ParticleSwarmLoader.tsx

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

import { motion } from "motion/react"
import { useMemo, useRef } from "react"

export interface ParticleSwarmLoaderProps {
  count?: number
  size?: number
  color?: string
  className?: string
}

function unit(seed: number) {
  const value = Math.sin(seed * 12.9898) * 43758.5453
  const fraction = value - Math.floor(value)
  return Math.round(fraction * 1e6) / 1e6
}

export function ParticleSwarmLoader({
  count = 50,
  size = 3,
  color = "#fb3a5d",
  className,
}: ParticleSwarmLoaderProps) {
  const ref = useRef<HTMLDivElement>(null)
  const prefersReducedMotion = usePrefersReducedMotion()
  const motionOn = useAnimationActive(ref)
  const animate = !prefersReducedMotion && motionOn
  const particles = useMemo(() => {
    const total = Math.max(count, 1)
    return Array.from({ length: total }, (_, index) => {
      const angle = (index / total) * Math.PI * 2
      return {
        id: index,
        x: Math.round((unit(index + 1) * 180 - 90) * 1e4) / 1e4,
        y: Math.round((unit(index + 11) * 180 - 90) * 1e4) / 1e4,
        ringX: Math.round(Math.cos(angle) * 62 * 1e4) / 1e4,
        ringY: Math.round(Math.sin(angle) * 62 * 1e4) / 1e4,
        radius: Math.round(size * (0.6 + unit(index + 5) * 0.8) * 1e4) / 1e4,
      }
    })
  }, [count, size])

  return (
    <div
      className={cn("h-40 w-40 overflow-hidden", className)}
      data-reduced={prefersReducedMotion ? "true" : "false"}
      data-slot="particle-swarm-loader"
      ref={ref}
    >
      <svg aria-hidden="true" className="size-full" viewBox="-100 -100 200 200">
        {particles.map((particle) => (
          <motion.circle
            initial={false}
            animate={
              animate
                ? { opacity: [0.2, 1, 0.2], cx: [particle.x, 0, particle.x], cy: [particle.y, 0, particle.y] }
                : { opacity: 1, cx: particle.ringX, cy: particle.ringY }
            }
            cx={animate ? particle.x : particle.ringX}
            cy={animate ? particle.y : particle.ringY}
            fill={color}
            key={particle.id}
            r={particle.radius}
            transition={
              animate
                ? { duration: 3, repeat: Infinity, ease: "easeInOut", delay: (particle.id % 8) * 0.12 }
                : { duration: 0 }
            }
          />
        ))}
      </svg>
    </div>
  )
}

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { cn } from "@/lib/utils"

interface Particle {
  x: number
  y: number
  vx: number
  vy: number
  size: number
}

export interface ParticlesProps extends React.HTMLAttributes<HTMLCanvasElement> {
  quantity?: number
  staticity?: number
  ease?: number
  color?: string
}

function watchDevicePixelRatio(onChange: () => void) {
  let media = window.matchMedia(`(resolution: ${window.devicePixelRatio}dppx)`)
  const handle = () => {
    media.removeEventListener("change", handle)
    media = window.matchMedia(`(resolution: ${window.devicePixelRatio}dppx)`)
    media.addEventListener("change", handle)
    onChange()
  }
  media.addEventListener("change", handle)
  return () => media.removeEventListener("change", handle)
}

function Particles({
  className,
  quantity = 60,
  staticity = 50,
  ease = 50,
  color = "currentColor",
  ...props
}: ParticlesProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const active = useAnimationActive(canvasRef)
  const particles = React.useRef<Particle[]>([])
  const mouse = React.useRef({ x: 0, y: 0 })

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || !active) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return

    let frame = 0
    let running = false
    let width = 0
    let height = 0
    let dpr = 0
    const motionMedia = window.matchMedia("(prefers-reduced-motion: reduce)")
    let reducedMotion = motionMedia.matches

    const syncSize = (nextWidth: number, nextHeight: number) => {
      const nextDpr = Math.min(window.devicePixelRatio || 1, 2)
      if (nextWidth * nextDpr < 1 || nextHeight * nextDpr < 1) return
      const sizeChanged = nextWidth !== width || nextHeight !== height
      if (!sizeChanged && nextDpr === dpr) return
      width = nextWidth
      height = nextHeight
      dpr = nextDpr
      canvas.width = width * dpr
      canvas.height = height * dpr
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      if (!sizeChanged) return
      particles.current = Array.from({ length: quantity }, () => ({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: (Math.random() - 0.5) * 0.4,
        vy: (Math.random() - 0.5) * 0.4,
        size: Math.random() * 1.6 + 0.4,
      }))
    }

    const onMove = (event: MouseEvent) => {
      const rect = canvas.getBoundingClientRect()
      mouse.current = {
        x: event.clientX - rect.left,
        y: event.clientY - rect.top,
      }
    }

    const draw = () => {
      ctx.clearRect(0, 0, width, height)
      ctx.fillStyle = color
      const attraction = (100 - staticity) / 1800
      const damping = ease / 1400

      for (const particle of particles.current) {
        const dx = mouse.current.x - particle.x
        const dy = mouse.current.y - particle.y
        particle.vx += dx * attraction
        particle.vy += dy * attraction
        particle.vx *= 1 - damping
        particle.vy *= 1 - damping
        particle.x += particle.vx
        particle.y += particle.vy

        if (particle.x < 0 || particle.x > width) particle.vx *= -1
        if (particle.y < 0 || particle.y > height) particle.vy *= -1

        ctx.beginPath()
        ctx.globalAlpha = 0.7
        ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2)
        ctx.fill()
      }

      if (!reducedMotion) frame = window.requestAnimationFrame(draw)
    }

    const stop = () => {
      running = false
      window.cancelAnimationFrame(frame)
    }

    const start = () => {
      if (width <= 0 || height <= 0) return
      if (reducedMotion) {
        stop()
        draw()
        return
      }
      if (running) return
      running = true
      frame = window.requestAnimationFrame(draw)
    }

    const onMotionChange = () => {
      reducedMotion = motionMedia.matches
      if (reducedMotion) {
        stop()
        if (width > 0 && height > 0) draw()
        return
      }
      start()
    }
    motionMedia.addEventListener("change", onMotionChange)

    const resizeObserver = new ResizeObserver((entries) => {
      const entry = entries[0]
      if (!entry) return
      syncSize(entry.contentRect.width, entry.contentRect.height)
      start()
    })

    const stopDprWatch = watchDevicePixelRatio(() => {
      syncSize(width, height)
      if (reducedMotion) start()
    })

    resizeObserver.observe(canvas)
    canvas.addEventListener("mousemove", onMove)

    return () => {
      stop()
      resizeObserver.disconnect()
      stopDprWatch()
      motionMedia.removeEventListener("change", onMotionChange)
      canvas.removeEventListener("mousemove", onMove)
    }
  }, [active, color, ease, quantity, staticity])

  return (
    <canvas
      ref={canvasRef}
      data-slot="particles"
      className={cn("pointer-events-auto absolute inset-0 size-full", className)}
      {...props}
    />
  )
}

export { Particles }

