import { useId, useRef, useState } from "react"
import { ChevronLeft } from "lucide-react"
import { LayoutGroup, motion } from "motion/react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface AlbumPhoto {
  id: string
  src: string
}

export interface AlbumCollection {
  id: string
  title: string
  subtitle: string
  photos: AlbumPhoto[]
}

function swatch(title: string, hue: number) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="480" height="480"><rect width="480" height="480" fill="hsl(${hue} 38% 46%)"/><circle cx="360" cy="90" r="36" fill="white" fill-opacity="0.7"/></svg>`
  return `data:image/svg+xml,${encodeURIComponent(svg)}`
}

function album(id: string, title: string, subtitle: string, hue: number): AlbumCollection {
  return {
    id,
    title,
    subtitle,
    photos: Array.from({ length: 6 }, (_, index) => ({
      id: `${id}-${index + 1}`,
      src: swatch(title, hue + index * 10),
    })),
  }
}

export const DEFAULT_ALBUMS: AlbumCollection[] = [
  album("c1", "Travel & Exploration", "Private", 198),
  album("c2", "Industrial Design", "Private", 220),
  album("c3", "Modern Architecture", "Private", 210),
  album("c4", "Abstract Art", "Public", 280),
]

export interface PhotoAlbumsProps {
  collections?: AlbumCollection[]
  color?: string
  duration?: number
  intensity?: number
  size?: number
  className?: string
}

export function PhotoAlbums({
  collections = DEFAULT_ALBUMS,
  color = "var(--foreground)",
  duration = 480,
  intensity = 14,
  size = 136,
  className,
}: PhotoAlbumsProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const live = useAnimationActive(rootRef)
  const reduced = usePrefersReducedMotion()
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const layoutGroupId = useId()
  const selected = collections.find((item) => item.id === selectedId) ?? null
  const spring = reduced || !live ? { duration: 0 } : { type: "spring" as const, stiffness: 280, damping: 32, mass: 1 }
  const fade = reduced || !live ? { duration: 0 } : { duration: duration / 1000 }

  return (
    <div
      ref={rootRef}
      data-open={selectedId ?? "none"}
      data-motion={live ? "on" : "off"}
      data-reduced={reduced ? "true" : "false"}
      className={cn("flex w-full max-w-md flex-col px-4 py-6 text-[var(--foreground)]", className)}
      style={{ color }}
    >
      <LayoutGroup id={layoutGroupId}>
        {selected ? (
          <div className="flex min-h-0 flex-col">
            <button
              type="button"
              onClick={() => setSelectedId(null)}
              className="mb-4 flex size-12 items-center justify-center rounded-full bg-[var(--muted)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--ring)] motion-reduce:transform-none"
            >
              <ChevronLeft size={24} strokeWidth={2.5} />
              <span className="sr-only">Go back</span>
            </button>
            <motion.h2 layoutId={`title-${selected.id}`} transition={spring} className="mb-4 text-3xl font-medium tracking-tight">
              {selected.title}
            </motion.h2>
            <div className="grid grid-cols-2 gap-4">
              {selected.photos.map((photo) => (
                <motion.div
                  key={photo.id}
                  layoutId={`photo-${photo.id}`}
                  transition={spring}
                  className="aspect-square overflow-hidden rounded-2xl bg-[var(--muted)] ring-1 ring-[var(--border)]"
                >
                  <img src={photo.src} alt="" className="h-full w-full object-cover" />
                </motion.div>
              ))}
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-x-8 gap-y-10">
            {collections.map((collection) => (
              <button
                key={collection.id}
                type="button"
                onClick={() => setSelectedId(collection.id)}
                className="group flex flex-col items-center outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--ring)]"
              >
                <span className="relative mb-3 flex aspect-square w-full items-center justify-center">
                  {collection.photos.slice(0, 3).map((photo, index) => {
                    const rotations = [-intensity, intensity, 0]
                    return (
                      <motion.span
                        key={photo.id}
                        layoutId={`photo-${photo.id}`}
                        className="absolute overflow-hidden rounded-3xl bg-[var(--muted)] ring-1 ring-[var(--border)] motion-reduce:transform-none"
                        style={{ width: size * 0.72, height: size * 0.72 }}
                        animate={{ rotate: reduced ? 0 : (rotations[index] ?? 0) }}
                        transition={fade}
                      >
                        <img src={photo.src} alt="" className="pointer-events-none h-full w-full object-cover" />
                      </motion.span>
                    )
                  })}
                </span>
                <motion.span layoutId={`title-${collection.id}`} transition={spring} className="text-center text-base font-medium">
                  {collection.title}
                </motion.span>
                <span className="sr-only">{collection.subtitle}</span>
              </button>
            ))}
          </div>
        )}
      </LayoutGroup>
    </div>
  )
}

export default PhotoAlbums

// @vitest-environment jsdom

import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"
import Matter from "matter-js"

import { PhysicsDropzone } from "./physics-dropzone"

let reduceMotion = false
let now = 0
let rafId = 0
let created = 0
const queue = new Map<number, FrameRequestCallback>()

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  created = 0
  queue.clear()
  const original = Matter.Engine.create
  vi.spyOn(Matter.Engine, "create").mockImplementation((options) => {
    created += 1
    return original.call(Matter.Engine, options)
  })
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
})

afterEach(() => {
  cleanup()
  vi.restoreAllMocks()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function dragIn(name: string, pointerType: "mouse" | "touch" = "mouse") {
  const file = screen.getByRole("button", { name })
  fireEvent.pointerDown(file, { clientX: 0, clientY: 0, pointerId: 1, pointerType, timeStamp: 0 })
  fireEvent.pointerMove(file, { clientX: 8, clientY: 70, pointerId: 1, pointerType, timeStamp: 30 })
  fireEvent.pointerUp(file, { clientX: 8, clientY: 96, pointerId: 1, pointerType, timeStamp: 60 })
}

test("默认渲染三个文件，不读减弱动效时没有 data-reduced", () => {
  render(<PhysicsDropzone />)
  expect(screen.getByRole("button", { name: "简报.pdf" })).toBeInTheDocument()
  expect(screen.getByRole("button", { name: "封面.png" })).toBeInTheDocument()
  expect(screen.getByRole("button", { name: "笔记.md" })).toBeInTheDocument()
  expect(screen.getByRole("region", { name: "落点" })).toHaveTextContent("拖进这里，文件会落成一堆")
  expect(screen.queryByRole("progressbar")).toBeNull()
  expect(document.querySelector("[data-slot='physics-dropzone']")).not.toHaveAttribute("data-reduced")
  expect(created).toBe(0)
  expect(queue.size).toBe(0)
})

test("拖进落点后下落并走完进度，再回调", () => {
  const onDrop = vi.fn()
  render(<PhysicsDropzone onDrop={onDrop} />)
  dragIn("简报.pdf")
  expect(created).toBe(1)
  expect(document.querySelector("[data-slot='physics-dropzone']")).toHaveAttribute("data-live", "true")
  expect(screen.getByRole("progressbar", { name: "简报.pdf" })).toHaveAttribute("aria-valuenow", "0")
  expect(onDrop).not.toHaveBeenCalled()
  pump(24)
  expect(onDrop).toHaveBeenCalledWith("brief")
  expect(screen.getByRole("progressbar", { name: "简报.pdf" })).toHaveAttribute("aria-valuenow", "100")
  expect(document.querySelector("[data-pile='true']")).toHaveTextContent("简报.pdf")
  expect(document.querySelector("[data-settled='true']")).toBeTruthy()
})

test("拖得不够远时文件不进入落点", () => {
  const onDrop = vi.fn()
  render(<PhysicsDropzone onDrop={onDrop} />)
  const file = screen.getByRole("button", { name: "简报.pdf" })
  fireEvent.pointerDown(file, { clientX: 0, clientY: 0, pointerId: 1, timeStamp: 0 })
  fireEvent.pointerUp(file, { clientX: 4, clientY: 8, pointerId: 1, timeStamp: 40 })
  pump(8)
  expect(onDrop).not.toHaveBeenCalled()
  expect(screen.getByRole("button", { name: "简报.pdf" })).toBeInTheDocument()
  expect(created).toBe(0)
  expect(queue.size).toBe(0)
})

test("方向键和回车都能把文件放进落点", () => {
  const onDrop = vi.fn()
  render(<PhysicsDropzone onDrop={onDrop} />)
  fireEvent.keyDown(screen.getByRole("button", { name: "简报.pdf" }), { key: "ArrowDown" })
  expect(screen.getByRole("progressbar", { name: "简报.pdf" })).toHaveAttribute("aria-valuenow", "0")
  pump(24)
  expect(onDrop).toHaveBeenCalledWith("brief")
  fireEvent.keyDown(screen.getByRole("button", { name: "封面.png" }), { key: "Enter" })
  pump(24)
  expect(onDrop).toHaveBeenCalledWith("shot")
  expect(screen.getAllByRole("progressbar")).toHaveLength(2)
})

test("触屏拖进落点后同样下落", () => {
  const onDrop = vi.fn()
  render(<PhysicsDropzone onDrop={onDrop} />)
  dragIn("笔记.md", "touch")
  pump(24)
  expect(onDrop).toHaveBeenCalledWith("notes")
  expect(screen.getByRole("progressbar", { name: "笔记.md" })).toHaveAttribute("aria-valuenow", "100")
})

test("减弱动效时文件直接出现在堆里，不创建引擎也不申请动画帧", () => {
  reduceMotion = true
  const onDrop = vi.fn()
  render(<PhysicsDropzone onDrop={onDrop} />)
  expect(document.querySelector("[data-slot='physics-dropzone']")).toHaveAttribute("data-reduced", "true")
  fireEvent.keyDown(screen.getByRole("button", { name: "简报.pdf" }), { key: "Enter" })
  expect(onDrop).toHaveBeenCalledWith("brief")
  expect(screen.getByRole("progressbar", { name: "简报.pdf" })).toHaveAttribute("aria-valuenow", "100")
  expect(document.querySelector("[data-settled='true']")).toBeTruthy()
  expect(document.querySelector("[data-live='true']")).toBeNull()
  expect(created).toBe(0)
  expect(queue.size).toBe(0)
})

