"use client"

import * as React from "react"
import { motion } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface PollOption {
  id: string
  label: string
  votes: number
}

export interface PollVoteProps {
  className?: string
  question?: string
  options?: PollOption[]
  mode?: "single" | "multiple"
  value?: string[]
  defaultValue?: string[]
  onVote?: (value: string[]) => void
  deadline?: number
  now?: number
}

const FROZEN_NOW = Date.parse("2026-10-20T18:00:00Z")

const STARTER: PollOption[] = [
  { id: "a", label: "本周发布", votes: 18 },
  { id: "b", label: "下周再看", votes: 11 },
  { id: "c", label: "先做内部试用", votes: 7 },
]

function relativeDeadline(deadline: number, now: number) {
  const minutes = Math.round((deadline - now) / 60000)
  const format = new Intl.RelativeTimeFormat("zh", { numeric: "auto" })
  if (Math.abs(minutes) < 90) return format.format(minutes, "minute")
  const hours = Math.round(minutes / 60)
  if (Math.abs(hours) < 36) return format.format(hours, "hour")
  return format.format(Math.round(hours / 24), "day")
}

function PollVote({
  className,
  question = "这个功能什么时候发出去？",
  options = STARTER,
  mode = "single",
  value,
  defaultValue = [],
  onVote,
  deadline = FROZEN_NOW + 2 * 24 * 60 * 60 * 1000,
  now = FROZEN_NOW,
}: PollVoteProps) {
  const reduced = usePrefersReducedMotion()
  const [internal, setInternal] = React.useState(defaultValue)
  const selected = value ?? internal
  const voted = selected.length > 0
  const counts = options.map((option) => option.votes + (selected.includes(option.id) ? 1 : 0))
  const total = counts.reduce((sum, count) => sum + count, 0)
  const highest = Math.max(...counts)
  const when = relativeDeadline(deadline, now)

  const choose = (id: string) => {
    const next =
      mode === "single" ? [id] : selected.includes(id) ? selected.filter((item) => item !== id) : [...selected, id]
    if (value === undefined) setInternal(next)
    onVote?.(next)
  }

  return (
    <div data-slot="poll-vote" className={cn("w-full max-w-md space-y-3 rounded-xl border p-4", className)}>
      <div className="flex items-start justify-between gap-3">
        <h3 className="text-sm font-medium">{question}</h3>
        <p className="text-xs text-muted-foreground">截止 {when}</p>
      </div>
      <div role={mode === "single" ? "radiogroup" : "group"} aria-label={question} className="space-y-2">
        {options.map((option, index) => {
          const count = counts[index] ?? 0
          const percent = total > 0 ? Math.round((count / total) * 100) : 0
          const active = selected.includes(option.id)
          const leading = voted && count === highest && count > 0
          return (
            <button
              key={option.id}
              type="button"
              role={mode === "single" ? "radio" : "checkbox"}
              aria-checked={active}
              onClick={() => choose(option.id)}
              className={cn(
                "relative w-full overflow-hidden rounded-lg border px-3 py-2 text-left text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary",
                leading && "border-primary",
              )}
            >
              {voted ? (
                <motion.span
                  className="absolute inset-y-0 left-0 bg-primary/15"
                  initial={false}
                  animate={{ width: `${percent}%` }}
                  transition={reduced ? { duration: 0 } : { type: "spring", stiffness: 180, damping: 24 }}
                />
              ) : null}
              <span className="relative flex items-center justify-between gap-3">
                <span>{option.label}</span>
                {voted ? <span>{percent}%</span> : null}
              </span>
            </button>
          )
        })}
      </div>
      <p aria-live="polite" className="text-xs text-muted-foreground">
        {voted ? `共 ${total} 票` : mode === "multiple" ? "可以选择多项" : "选择一项"}
      </p>
    </div>
  )
}

export { PollVote }

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { cn } from "@/lib/utils"

export interface PolylineRibbonCursorProps {
  className?: string
  color?: string
  points?: number
  speed?: number
  intensity?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

function useReducedMotion() {
  return React.useSyncExternalStore(
    (onChange) => {
      const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
      mq.addEventListener("change", onChange)
      return () => mq.removeEventListener("change", onChange)
    },
    () => window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    () => false,
  )
}

function PolylineRibbonCursor({ className, color = "#a78bfa", points = 18, speed, intensity }: PolylineRibbonCursorProps) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const reduced = useReducedMotion()
  const [fallback, setFallback] = React.useState(false)
  const [trail, setTrail] = React.useState<string>("")
  const mouse = React.useRef({ x: 0, y: 0 })
  const active = useAnimationActive(hostRef)
  const activeRef = React.useRef(false)
  const kickRef = React.useRef<(() => void) | null>(null)
  const speedRef = React.useRef(pace(speed))
  const gain = intensity === undefined || intensity === 1 ? 1 : intensity
  const gainRef = React.useRef(gain)

  React.useEffect(() => {
    speedRef.current = pace(speed)
    gainRef.current = intensity === undefined || intensity === 1 ? 1 : intensity
  }, [speed, intensity])

  React.useEffect(() => {
    activeRef.current = active
    if (active) kickRef.current?.()
  }, [active])

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || reduced) return

    let cancelled = false
    let frame = 0

    const run = async () => {
      const ogl = await import("ogl")
      if (!canvas || cancelled) return
      const renderer = new ogl.Renderer({ canvas, alpha: true, dpr: Math.min(window.devicePixelRatio || 1, 1.5) })
      const gl = renderer.gl
      gl.clearColor(0, 0, 0, 0)
      const camera = new ogl.Camera(gl, { fov: 15 })
      camera.position.z = 3
      const scene = new ogl.Transform()
      const curve = Array.from({ length: points }, () => new ogl.Vec3())
      const polyline = new ogl.Polyline(gl, {
        points: curve,
        uniforms: {
          uThickness: { value: 18 * gainRef.current },
          uColor: { value: new ogl.Color(color) },
        },
      })
      polyline.mesh.setParent(scene)

      const resize = () => {
        const { width, height } = canvas.getBoundingClientRect()
        renderer.setSize(width, height)
        camera.perspective({ aspect: width / Math.max(height, 1) })
        polyline.resize()
      }
      resize()

      const tick = () => {
        if (!activeRef.current) {
          frame = 0
          return
        }
        const { width, height } = canvas.getBoundingClientRect()
        const nx = (mouse.current.x / Math.max(width, 1)) * 2 - 1
        const ny = -((mouse.current.y / Math.max(height, 1)) * 2 - 1)
        const rate = speedRef.current
        curve[0]?.lerp(new ogl.Vec3(nx, ny, 0), 0.45 * rate)
        for (let i = 1; i < curve.length; i += 1) {
          curve[i]?.lerp(curve[i - 1] ?? new ogl.Vec3(), 0.32 * rate)
        }
        const thickness = polyline.mesh.program.uniforms.uThickness
        if (thickness) thickness.value = 18 * gainRef.current
        polyline.updateGeometry()
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      kickRef.current = () => {
        if (activeRef.current && frame === 0) frame = window.requestAnimationFrame(tick)
      }
      kickRef.current()
      window.addEventListener("resize", resize)
      return () => {
        kickRef.current = null
        window.cancelAnimationFrame(frame)
        window.removeEventListener("resize", resize)
      }
    }

    const cleanup = run().catch(() => {
      if (!cancelled) queueMicrotask(() => setFallback(true))
    })
    return () => {
      cancelled = true
      kickRef.current = null
      void cleanup.then((fn) => fn?.())
    }
  }, [color, points, reduced])

  return (
    <div
      ref={hostRef}
      data-slot="polyline-ribbon-cursor"
      className={cn("relative min-h-52 overflow-hidden rounded-xl border bg-zinc-950", className)}
      onPointerMove={(event) => {
        const rect = event.currentTarget.getBoundingClientRect()
        mouse.current.x = event.clientX - rect.left
        mouse.current.y = event.clientY - rect.top
        setTrail((prev) => {
          const next = `${mouse.current.x.toFixed(1)},${mouse.current.y.toFixed(1)}`
          const points = prev ? [...prev.split(" ").slice(-24), next] : [next]
          return points.join(" ")
        })
      }}
    >
      {fallback || reduced ? (
        <svg className="absolute inset-0 size-full">
          <polyline points={trail} fill="none" stroke={color} strokeWidth={6 * gain} strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      ) : (
        <canvas ref={canvasRef} className="absolute inset-0 size-full" />
      )}
      <p className="relative z-10 grid min-h-52 place-items-center text-sm text-white/60">移动指针画出丝带</p>
    </div>
  )
}

export { PolylineRibbonCursor }

