              <p className="text-xs text-muted-foreground">{item.category}</p>
              <h3 className="mt-1 text-sm font-medium">{item.title}</h3>
              <p className="mt-1 text-xs text-muted-foreground">{item.summary}</p>
            </motion.article>
          ))}
        </div>
      )}
    </section>
  )
}

